function parseThresholdsFromCli(thresholdArgs?: string[]): Record<string, number> | null {
  if (!thresholdArgs || thresholdArgs.length === 0) {
    return null;
  }

  const thresholds: Record<string, number> = {};

  for (const arg of thresholdArgs) {
    const match = arg.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      throw new Error(`Malformed threshold: ${arg}. Expected format: <metric>=<number>`);
    }

    const [, metric, value] = match;
    const num = parseFloat(value);

    if (isNaN(num) || num < 0 || num > 1) {
      throw new Error(
        `Invalid threshold value: ${arg}. Minimum must be a number between 0 and 1.`
      );
    }

    thresholds[metric] = num;
  }

  return Object.keys(thresholds).length > 0 ? thresholds : null;
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);

  let thresholds: Record<string, number> | null = null;
  try {
    thresholds = parseThresholdsFromCli(options.threshold);
  } catch (error) {
    log.error('Invalid threshold option.', {
      error: error instanceof Error ? error.message : String(error)
    });
    process.exit(2);
  }

  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  let report: unknown;
  try {
    report = (Eval.generateReport as unknown as (config: unknown) => any)({
      evaluations,
      outputsPath: dataset.outputsPath,
      referencesPath: dataset.referencesPath,
      thresholds
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    if (message.includes('Unknown metric ID')) {
      log.error('Unknown metric in threshold.', { error: message });
      process.exit(2);
    }
    throw error;
  }

  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  const reportWithThresholds = report as any;
  if (reportWithThresholds.passed === false) {
    log.error('Evaluation failed: one or more thresholds were not met.');
    process.exit(1);
  }
}

