it('evaluates thresholds that pass', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: ['hello']
  });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    thresholds: { exact_match: 0.5, toxicity: 0.5 },
    generatedAt: '2024-01-01T00:00:00.000Z'
  });

  expect(report.passed).toBe(true);
  expect(report.thresholds).toHaveLength(2);
  const exactMatch = report.thresholds.find((t) => t.metric === 'exact_match');
  expect(exactMatch.passed).toBe(true);
  expect(exactMatch.score).toBe(1);
  expect(exactMatch.min).toBe(0.5);
});

it('evaluates thresholds that fail', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: ['world']
  });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: '/tmp/refs.json',
    thresholds: { exact_match: 0.9 },
    generatedAt: '2024-01-01T00:00:00.000Z'
  });

  expect(report.passed).toBe(false);
  expect(report.thresholds).toHaveLength(1);
  const exactMatch = report.thresholds[0];
  expect(exactMatch.passed).toBe(false);
  expect(exactMatch.score).toBe(0);
  expect(exactMatch.min).toBe(0.9);
});

it('handles metrics without scores', () => {
  const evaluations = [
    {
      id: 'exact_match',
      label: 'Exact Match',
      score: null,
      total: 0,
      matches: 0,
      details: 'No references provided'
    }
  ];
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/outputs.json',
    referencesPath: null,
    thresholds: { exact_match: 0.9 },
    generatedAt: '2024-01-01T00:00:00.000Z'
  });

  expect(report.passed).toBe(false);
  expect(report.thresholds[0].passed).toBe(false);
  expect(report.thresholds[0].score).toBe(null);
});

it('throws error for unknown metric ID', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: ['hello']
  });

  expect(() => {
    generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { unknown_metric: 0.5 },
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
  }).toThrow(/Unknown metric ID/);
});

it('throws error for invalid threshold value', () => {
  const evaluations = runEvaluations({
    outputs: ['Hello'],
    references: ['hello']
  });

  expect(() => {
    generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 1.5 },
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
  }).toThrow(/must be a number between 0 and 1/);
});

